mapper.update:
UPDATE `kkirikkiri`.`articles`
SET view = view + 1
WHERE id = #{id}

mapper.select:
SELECT `t1`.`id` AS `id`, `t1`.`board_id` AS `boardId`, `t1`.`user_id` AS `userId`, `t1`.`participants_id` AS `participantsId`, `t1`.`wallet_id` AS `walletId`, `t1`.`title` AS `title`, `t1`.`menu` AS `menu`, `t1`.`menu_name` AS `menuName`, `t1`.`min_order_price` AS `minOrderPrice`, `t1`.`order_price` AS `orderPrice`, `t1`.`delivery_price` AS `deliveryPrice`, `t1`.`order_time` AS `orderTime`, `t1`.`pickup_time` AS `pickupTime`, `t1`.`restaurant` AS `restaurant`, `t1`.`point_lat` AS `pointLat`, `t1`.`point_lng` AS `pointLng`, `t1`.`address_primary` AS `addressPrimary`, `t1`.`address_secondary` AS `addressSecondary`, `t1`.`content` AS `content`, `t1`.`isShareChecked` AS `shareChecked`, `t1`.`isEntryChecked` AS `entryChecked`, `t1`.`created_at` AS `createdAt`, `t1`.`updated_at` AS `updatedAt`, `t1`.`view` AS `view`, `t2`.`nickname` AS `nickname` FROM `kkirikkiri`.`articles` AS `t1` LEFT JOIN `kkirikkiri`.`users` AS `t2` ON `t2`.`email` = `t1`.`user_id` WHERE `t1`.`board_id` = #{boardSearch.id}
AND (`t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`content` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`user_id` LIKE CONCAT('%', #{boardSearch.keyword}, '%'))
AND `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
AND `t2`.`nickname` LIKE CONCAT ('%', #{boardSearch.keyword}, '%')
ORDER BY `t1`.`id` DESC LIMIT #{boardPage.rowCount} OFFSET #{boardPage.dbOffset}

SELECT `t1`.`id` AS `id`, `t1`.`board_id` AS `boardId`, `t1`.`user_id` AS `userId`, `t1`.`participants_id` AS `participantsId`, `t1`.`wallet_id` AS `walletId`, `t1`.`title` AS `title`, `t1`.`menu` AS `menu`, `t1`.`menu_name` AS `menuName`, `t1`.`min_order_price` AS `minOrderPrice`, `t1`.`order_price` AS `orderPrice`, `t1`.`delivery_price` AS `deliveryPrice`, `t1`.`order_time` AS `orderTime`, `t1`.`pickup_time` AS `pickupTime`, `t1`.`restaurant` AS `restaurant`, `t1`.`point_lat` AS `pointLat`, `t1`.`point_lng` AS `pointLng`, `t1`.`address_primary` AS `addressPrimary`, `t1`.`address_secondary` AS `addressSecondary`, `t1`.`content` AS `content`, `t1`.`isShareChecked` AS `shareChecked`, `t1`.`isEntryChecked` AS `entryChecked`, `t1`.`created_at` AS `createdAt`, `t1`.`updated_at` AS `updatedAt`, `t1`.`view` AS `view` FROM `kkirikkiri`.`articles`AS `t1` WHERE `board_id` = #{boardId} AND `t1`.`order_time` IS NOT NULL AND `t1`.`order_time` BETWEEN DATE_ADD(NOW(), INTERVAL 20 MINUTE) AND DATE_ADD(NOW(), INTERVAL 60 MINUTE) AND `point_lat` BETWEEN #{location.lat} - 3.0/111 AND #{location.lat} + 3.0/111 AND `point_lng` BETWEEN #{location.lng} - (3.0 / (111 * COS(RADIANS(#{location.lat})))) AND #{location.lng} + (3.0 / (111 * COS(RADIANS(#{location.lat})))) AND ST_DISTANCE_SPHERE(POINT(`point_lng`,`point_lat`), POINT(#{location.lng}, #{location.lat})) <= 3000
AND `menu` = #{menu}
ORDER BY `t1`.`order_time` ASC LIMIT 10
